<?php
/**
 * Page Generator logic for Executive Acquisition theme
 */

/**
 * Register Customizer settings for the Page Generator
 */
function ea_generator_customize_register( $wp_customize ) {
    $wp_customize->add_section( 'ea_generator_section', array(
        'title'    => __( 'Page Generator / Setup', 'executive-acquisition' ),
        'priority' => 20,
        'description' => __( 'Use this tool to automatically generate or reset the core funnel pages. Warning: This will delete existing pages generated by this theme.', 'executive-acquisition' ),
    ) );

    // We use a dummy setting and a custom control for the button
    $wp_customize->add_setting( 'ea_regenerate_trigger', array(
        'default'           => '',
        'sanitize_callback' => 'sanitize_text_field',
    ) );

    $wp_customize->add_control( new EA_Generator_Control( $wp_customize, 'ea_regenerate_trigger', array(
        'label'    => __( 'Regenerate Funnel Pages', 'executive-acquisition' ),
        'section'  => 'ea_generator_section',
        'settings' => 'ea_regenerate_trigger',
    ) ) );
}
add_action( 'customize_register', 'ea_generator_customize_register' );

/**
 * Custom Control for the Regenerate Button
 */
if ( class_exists( 'WP_Customize_Control' ) ) {
    class EA_Generator_Control extends WP_Customize_Control {
        public $type = 'ea_generator_button';

        public function render_content() {
            ?>
            <label>
                <span class="customize-control-title"><?php echo esc_html( $this->label ); ?></span>
                <button type="button" class="button button-primary ea-generator-btn" id="ea-regenerate-btn">
                    <?php _e( 'Generate / Reset Infrastructure', 'executive-acquisition' ); ?>
                </button>
                <span class="spinner" style="float:none; vertical-align: middle;"></span>
                <p class="description" style="margin-top: 10px;">
                    <?php _e( 'This will create: Home, Thank You, Briefing, Blog, ROI Proof, and a Primary Menu.', 'executive-acquisition' ); ?>
                </p>
            </label>
            <script type="text/javascript">
                jQuery(document).ready(function($) {
                    $('#ea-regenerate-btn').on('click', function(e) {
                        e.preventDefault();
                        if (!confirm('Are you sure? This will delete previously generated pages and menus.')) return;

                        var $btn = $(this);
                        var $spinner = $btn.next('.spinner');

                        $btn.attr('disabled', true);
                        $spinner.addClass('is-active');

                        $.post(ajaxurl, {
                            action: 'ea_generate_pages',
                            nonce: '<?php echo wp_create_nonce("ea_generator_nonce"); ?>'
                        }, function(response) {
                            $btn.attr('disabled', false);
                            $spinner.removeClass('is-active');
                            alert(response.data.message);
                            if (response.success) {
                                location.reload();
                            }
                        });
                    });
                });
            </script>
            <?php
        }
    }
}

/**
 * AJAX Handler for Page Generation
 */
function ea_ajax_generate_pages() {
    check_ajax_referer( 'ea_generator_nonce', 'nonce' );

    if ( ! current_user_can( 'manage_options' ) ) {
        wp_send_json_error( array( 'message' => __( 'Insufficient permissions.', 'executive-acquisition' ) ) );
    }

    // 1. Delete old pages
    $old_pages = get_posts( array(
        'post_type'  => 'page',
        'meta_key'   => '_ea_generated_page',
        'posts_per_page' => -1,
    ) );

    foreach ( $old_pages as $p ) {
        wp_delete_post( $p->ID, true );
    }

    // 2. Delete old menus
    $old_menu = wp_get_nav_menu_object( 'Executive Primary Menu' );
    if ( $old_menu ) {
        wp_delete_nav_menu( $old_menu->term_id );
    }

    // 3. Generate new pages
    $pages_to_create = array(
        'Home' => array(
            'template' => 'front-page.php',
            'content'  => '',
        ),
        'Thank You' => array(
            'template' => 'template-thank-you.php',
            'content'  => '',
        ),
        'Executive Briefing' => array(
            'template' => 'template-briefing.php',
            'content'  => '',
        ),
        'Blog' => array(
            'template' => 'home.php',
            'content'  => '',
        ),
        'ROI Case Study' => array(
            'template' => 'template-case-study.php',
            'content'  => 'This is a sample ROI case study showing institutional impact.',
        ),
    );

    // Create Menu
    $menu_id = wp_create_nav_menu( 'Executive Primary Menu' );
    $locations = get_theme_mod( 'nav_menu_locations' );
    $locations['primary'] = $menu_id;
    set_theme_mod( 'nav_menu_locations', $locations );

    $created_count = 0;
    foreach ( $pages_to_create as $title => $data ) {
        $page_id = wp_insert_post( array(
            'post_title'   => $title,
            'post_content' => $data['content'],
            'post_status'  => 'publish',
            'post_type'    => 'page',
        ) );

        if ( $page_id ) {
            update_post_meta( $page_id, '_wp_page_template', $data['template'] );
            update_post_meta( $page_id, '_ea_generated_page', '1' );

            // Add to Menu (Exclude Thank You and Briefing from main nav if desired, but here we add all for demo)
            if ( $title !== 'Thank You' && $title !== 'Executive Briefing' ) {
                wp_update_nav_menu_item( $menu_id, 0, array(
                    'menu-item-title'     => $title,
                    'menu-item-object'    => 'page',
                    'menu-item-object-id' => $page_id,
                    'menu-item-type'      => 'post_type',
                    'menu-item-status'    => 'publish',
                ) );
            }

            // Set Reading Settings
            if ( $title === 'Home' ) {
                update_option( 'show_on_front', 'page' );
                update_option( 'page_on_front', $page_id );
            }
            if ( $title === 'Blog' ) {
                update_option( 'page_for_posts', $page_id );
            }
            $created_count++;
        }
    }

    wp_send_json_success( array( 'message' => sprintf( __( 'Success! %d funnel pages and Primary Menu generated.', 'executive-acquisition' ), $created_count ) ) );
}
add_action( 'wp_ajax_ea_generate_pages', 'ea_ajax_generate_pages' );
